CREATE TABLE authors (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL
);

CREATE TABLE books (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title text NOT NULL,
    author_id integer NOT NULL REFERENCES authors (id)
);

INSERT INTO authors (name) VALUES ('Ursula K. Le Guin'), ('Octavia E. Butler'), ('Frank Herbert');

INSERT INTO books (title, author_id)
VALUES ('A Wizard of Earthsea', 1), ('The Dispossessed', 1), ('Kindred', 2), ('Dune', 3);

SELECT b.title, a.name AS author
FROM books AS b
JOIN authors AS a ON a.id = b.author_id
ORDER BY b.title;

