practice.solution:
CREATE TABLE recipes (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL
);

CREATE TABLE ingredients (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL
);

INSERT INTO recipes (name) VALUES ('Pancakes'), ('Omelette');

INSERT INTO ingredients (name) VALUES ('eggs'), ('flour'), ('milk'), ('cheese');

CREATE TABLE recipe_ingredients (
    recipe_id integer REFERENCES recipes (id) ON DELETE CASCADE,
    ingredient_id integer REFERENCES ingredients (id) ON DELETE CASCADE,
    quantity text NOT NULL,
    PRIMARY KEY (recipe_id, ingredient_id)
);

INSERT INTO recipe_ingredients (recipe_id, ingredient_id, quantity)
VALUES (1, 2, '200 g'), (1, 3, '300 ml'), (1, 1, '2'), (2, 1, '3'), (2, 4, '50 g'), (2, 3, '50 ml');

SELECT r.name AS recipe, i.name AS ingredient, ri.quantity
FROM recipe_ingredients AS ri
JOIN recipes AS r ON r.id = ri.recipe_id
JOIN ingredients AS i ON i.id = ri.ingredient_id
ORDER BY r.name, i.name;
